11	function refuseDispatch(int $playerId, array $result, string $minutesAgo = '0 minutes'): void
12	{
13	    app(AiActionReceipt::class)->forceFill([
14	        'player_id' => $playerId,
15	        'idempotency_key' => 'test:' . uniqid(),
16	        'action_type' => AiActionType::DispatchFleet,
17	        'state' => AiReceiptState::Rejected,
18	        'result' => $result,
19	        'created_at' => now()->modify('-' . $minutesAgo),
20	        'updated_at' => now(),
21	    ])->save();
22	}
23	
24	// A refused dispatch is not a mission, so the planners never saw it and offered the same target again (21 times in six hours).
25	test('a target the gate just refused is remembered for a while, only for that account and that target', function (): void {
26	    refuseDispatch($this->currentUserId, ['reason' => 'target_active_at_dispatch', 'planet_id' => 7, 'decision' => ['target_galaxy' => 1, 'target_system' => 22, 'target_position' => 4]]);
