31	        ->and($refusals->target($this->currentUserId + 1, 1, 22, 4))->toBeFalse();
32	});
33	
34	test('a refusal is forgotten once the window passes', function (): void {
35	    refuseDispatch($this->currentUserId, ['reason' => 'target_active_at_dispatch', 'planet_id' => 7, 'decision' => ['target_galaxy' => 1, 'target_system' => 22, 'target_position' => 4]], '3 hours');
