 31	        ->resources(1_000_000, 1_000_000, 1_000_000)
 32	        ->ships('recycler', 2)
 33	        ->debris(40_000, 20_000)
 34	        ->session()
 35	        ->expectWork(AiWorkKind::Recycle);
 36	});
