  211	    private function queueClaimedIntent(AiProfile $profile, AiWorkItem $workItem, string $leaseToken): void
  212	    {
  213	        // The action cap bounds what a session may touch, not what it may think: at zero the
  214	        // session already decided and scheduled, so this pass closes its lease and acts on
  215	        // nothing.
  216	        if (!app(ResolveAiAdmissionAction::class)->forAction()->allowed) {
  217	            $this->completeLease($workItem, $leaseToken);
  218	
  219	            return;
  220	        }
  221	
  222	        $receipt = AiActionReceipt::query()->firstOrCreate(
  223	            ['idempotency_key' => $workItem->idempotency_key],
  224	            [
  225	                'player_id' => $workItem->player_id,
  226	                'action_type' => $workItem->kind->actionType(),
  227	                'state' => AiReceiptState::Processing,
  228	            ],
  229	        );
  230	        if (in_array($receipt->state, [AiReceiptState::Accepted, AiReceiptState::Completed, AiReceiptState::Rejected], true)) {
  231	            $this->completeLease($workItem, $leaseToken);
  232	
  233	            return;
  234	        }
  235	
  236	        $planetId = $this->ownedPlanetIdFor($workItem);
  237	        if ($planetId === 0) {
  238	            $receipt->update(['state' => AiReceiptState::Rejected, 'result' => [AiActionReceiptResultKey::Reason->value => AiQueueActionReason::NoOwnedPlanet->value]]);
  239	            $this->completeLease($workItem, $leaseToken);
  240	
  241	            return;
  242	        }
  243	
  244	        // An intent that names a body this account does not own is not this account's to act on, and
  245	        // re-planning it onto a different one would silently change what the session decided.
  246	        if (!Planet::query()->whereKey($planetId)->where('user_id', $workItem->player_id)->exists()) {
  247	            $receipt->update(['state' => AiReceiptState::Rejected, 'result' => [AiActionReceiptResultKey::Reason->value => AiQueueActionReason::PlanetNotOwned->value]]);
  248	            $this->completeLease($workItem, $leaseToken);
  249	
  250	            return;
  251	        }
  252	
  253	        [$result, $decision, $actedPlanetId] = app(ExecuteAiIntentAction::class)->execute($workItem, $planetId);
  254	        if ($result === null) {
  255	            $receipt->update(['state' => AiReceiptState::Rejected, 'result' => [AiActionReceiptResultKey::Reason->value => AiQueueActionReason::NothingQueueable->value]]);
