  257	
  258	            return;
  259	        }
  260	
  261	        $receipt->update([
  262	            'state' => $result->successful ? AiReceiptState::Accepted : AiReceiptState::Rejected,
  263	            'result' => [
  264	                AiActionReceiptResultKey::QueueId->value => $result->queueId,
  265	                AiActionReceiptResultKey::Reason->value => $result->reason,
  266	                AiActionReceiptResultKey::Decision->value => $decision,
  267	                AiActionReceiptResultKey::PlanetId->value => $actedPlanetId,
  268	            ],
  269	        ]);
  270	        $this->completeLease($workItem, $leaseToken);
  271	    }
