 66	    public function plan(int $playerId, ?PlayerService $player = null): ?QueueableSpy
 67	    {
 68	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
 69	        if ($profile === null) {
 70	            return null;
 71	        }
 72	
 73	        if (!User::query()->whereKey($playerId)->exists()) {
 74	            return null;
 75	        }
 76	
 77	        $player ??= $this->playerServiceFactory->make($playerId, true);
 78	
 79	        $refusals = app(RecentRefusals::class);
 80	        $skip = $this->freshIntelCoordinates($playerId)
 81	            + $this->inFlightCoordinates($playerId)
 82	            + $this->openSpyIntentCoordinates($playerId)
 83	            // A probe the gate just refused is not a mission, so nothing else remembers the target.
 84	            + $refusals->refusedTargets($playerId);
 85	        $selection = $this->target($player, $skip, $refusals->refusedOrigins($playerId));
 86	        if ($selection === null) {
 87	            return null;
 88	        }
 89	        [$origin, $target] = $selection;
 90	
 91	        return app()->makeWith(QueueableSpy::class, [
 92	            'planetId' => $origin->getPlanetId(),
 93	            'targetGalaxy' => (int) $target->galaxy,
 94	            'targetSystem' => (int) $target->system,
 95	            'targetPosition' => (int) $target->planet,
 96	            'targetType' => (int) $target->planet_type,
 97	            'missionType' => EspionageMission::getTypeId(),
 98	            'probeCount' => $this->probeCount($target),
 99	        ]);
100	    }
