102	    /**
103	     * Every own planet whose idle probes still exceed what its own pending spy intents
104	     * have committed (N6). A probe already promised to a queued or retried intent is not a
105	     * second probe, so two pending probes for different targets each plan from the budget
106	     * that remains after the other is committed.
107	     *
108	     * @return list<PlanetService>
109	     */
110	    private function idleProbePlanets(PlayerService $player): array
111	    {
112	        $committed = $this->committedProbesByPlanet($player->getId());
113	        $probeName = EspionageMission::getRequiredShipMachineNames()[0];
114	        $planets = [];
115	
116	        foreach ($player->planets->all() as $planet) {
117	            $idle = $planet->getShipUnits()->getAmountByMachineName($probeName);
118	
119	            if ($idle > ($committed[$planet->getPlanetId()] ?? 0)) {
120	                $planets[] = $planet;
121	            }
122	        }
123	
124	        return $planets;
125	    }
