127	    /** @return array<int, int> probes committed to open spy intents, keyed by the origin planet */
128	    private function committedProbesByPlanet(int $playerId): array
129	    {
130	        $committed = [];
131	
132	        foreach (AiWorkItem::query()
133	            ->where('player_id', $playerId)
134	            ->where('kind', AiWorkKind::Spy)
135	            ->whereIn('state', [AiWorkState::Pending, AiWorkState::Leased, AiWorkState::Retry])
136	            ->get(['payload']) as $item) {
137	            $payload = $item->payload ?? [];
138	            $planetId = (int) ($payload['planet_id'] ?? 0);
139	
140	            if ($planetId > 0) {
141	                $committed[$planetId] = ($committed[$planetId] ?? 0) + 1;
142	            }
143	        }
144	
145	        return $committed;
146	    }
