148	    /**
149	     * The best legal foreign target, scored instead of the first one in id order.
150	     *
151	     * Own, destroyed, vacationing and administrator-protected planets are all
152	     * skipped — the module restates no rule, it only declines candidates the
153	     * host's own mission would refuse. A planet the account already knows, or
154	     * already has a probe travelling toward, is skipped too. Among what remains,
155	     * a just-touched target is skipped (INT-009) and the rest are ranked by
156	     * known yield, what the target paid before and closeness (INT-003): the
157	     * closest known-rich neighbour, not the lowest id.
158	     *
159	     * @param array<string, true> $skipCoordinates
160	     * @param array<int, true> $refusedOrigins own bodies the gate just refused a dispatch from
161	     * @return array{0: PlanetService, 1: Planet}|null the origin and its target
162	     */
163	    private function target(PlayerService $player, array $skipCoordinates, array $refusedOrigins): ?array
164	    {
165	        $idleOrigins = array_values(array_filter(
166	            $this->idleProbePlanets($player),
167	            static fn (PlanetService $planet): bool => ! isset($refusedOrigins[$planet->getPlanetId()]),
168	        ));
169	        if ($idleOrigins === []) {
170	            return null;
171	        }
172	
173	        // A scout reads the neighbours nearest to home, not the oldest stamps in the universe: ordering by the
174	        // owner's last login pushed every cohort account (whose stamp is zero) behind the fixed farms, so
175	        // the nearest rivals were never read and nothing defended was ever raided. The farm-first ranking
176	        // below still picks the quiet body among the nearest, and the host's isInactive() stays the authority.
177	        $home = $idleOrigins[0]->getPlanetCoordinates();
178	        $candidates = Planet::query()
179	            ->leftJoin('users', 'users.id', '=', 'planets.user_id')
180	            ->where('planets.user_id', '!=', $player->getId())
181	            ->where('planets.destroyed', 0)
182	            ->where(fn ($owner) => $owner->whereNull('users.vacation_mode')->orWhere('users.vacation_mode', 0))
183	            ->whereIn('planets.planet_type', [PlanetType::Planet->value, PlanetType::Moon->value])
184	            ->select('planets.*')
185	            ->orderByRaw('ABS(CAST(`planets`.`galaxy` AS SIGNED) - ?) * 100000 + ABS(CAST(`planets`.`system` AS SIGNED) - ?) * 20 + ABS(CAST(`planets`.`planet` AS SIGNED) - ?), `planets`.`id`', [$home->galaxy, $home->system, $home->position])
186	            ->cursor()
187	            ->reject(static fn (Planet $planet): bool => isset($skipCoordinates["{$planet->galaxy}:{$planet->system}:{$planet->planet}"]))
188	            ->take(self::MAX_CANDIDATES)
189	            ->values();
190	
191	        $intel = $this->knownIntelByCoordinate($candidates);
192	        $knownYield = $intel['yield'];
193	        // What the account remembers about these planets: the priority counter, read in one pass so a
194	        // target that paid before is not priced once per candidate.
195	        $priorities = $this->intelBook->priorities($player->getId());
196	        $payoffWeight = $this->intelBook->priorityWeight();
197	        $fighter = $this->ownsWarFleet($idleOrigins);
198	        $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
199	        $scored = [];
200	
201	        foreach ($candidates as $planet) {
202	            $coordinateKey = "{$planet->galaxy}:{$planet->system}:{$planet->planet}";
203	            if (isset($skipCoordinates[$coordinateKey])) {
204	                continue;
205	            }
206	
207	            // The candidate model is already in hand; building a PlanetService
208	            // from it skips the per-candidate Planet::find + refreshUser that
209	            // make($id, true) would pay (20 candidates × 2 round trips).
210	            $target = $this->planetServiceFactory->makeFromModel($planet);
211	
212	            $owner = $target->getPlayer();
213	
214	            // The host's own protected-administrator signal, so the rule survives any operator rename.
215	            if ($owner?->isAdmin() === true) {
216	                continue;
217	            }
218	            $origin = $this->closestOrigin($player, $idleOrigins, $planet, $fleetMissions);
219	            if ($origin === null) {
220	                continue;
221	            }
222	            $distance = $fleetMissions->calculateFleetMissionDistance($origin, new Coordinate((int) $planet->galaxy, (int) $planet->system, (int) $planet->planet));
223	            $scored[] = [
224	                'planet' => $planet,
225	                'origin' => $origin,
226	                'inactive' => $owner?->isInactive() ?? false,
227	                'quiet' => !$this->activityIntelReader->activityAt($target),
228	                'defended' => $fighter && isset($intel['defended'][$coordinateKey]),
229	                'score' => ($knownYield[$coordinateKey] ?? 0.0) - $distance + $payoffWeight * ($priorities[$coordinateKey] ?? 0),
230	            ];
231	        }
232	
233	        if ($scored === []) {
234	            return null;
235	        }
236	
237	        // The farm comes first, then the neighbour away from the keyboard, then the one at it: a player who
238	        // has read every quiet body still scouts the active ones, since an account that acts every few
239	        // minutes is the only kind that fights back and leaves debris. Among equals the closest known-rich
240	        // body wins (INT-003).
241	        // An account that owns a war fleet reads the bodies known to fight back first: an administrator
242	        // sees raids that pillage empty planets as a dead universe (LIFE_FIGHTS), and a fleet is built
243	        // to be flown at something that shoots.
244	        usort($scored, static fn (array $left, array $right): int => [$right['defended'], $right['inactive'], $right['quiet'], $right['score']] <=> [$left['defended'], $left['inactive'], $left['quiet'], $left['score']]);
245	
246	        return [$scored[0]['origin'], $scored[0]['planet']];
247	    }
