249	    /**
250	     * Whether any scouting base stands a military hull, by the host's own military catalogue.
251	     *
252	     * @param list<PlanetService> $origins
253	     */
254	    private function ownsWarFleet(array $origins): bool
255	    {
256	        $military = array_map(static fn ($ship): string => $ship->machine_name, ObjectService::getMilitaryShipObjects());
257	
258	        foreach ($origins as $origin) {
259	            foreach ($origin->getShipUnits()->units as $entry) {
260	                // A probe is in the military catalogue but carries no real weapon: a war fleet shoots.
261	                $player = $origin->getPlayer();
262	                if ($player !== null && in_array($entry->unitObject->machine_name, $military, true) && $entry->unitObject->properties->attack->calculate($player)->totalValue > 1) {
263	                    return true;
264	                }
265	            }
266	        }
267	
268	        return false;
269	    }
