271	    /**
272	     * The own planet with an idle probe closest to the target that can pay the flight, not the first in
273	     * collection order: a probe is fuel and time, so the nearest base that has the deuterium sends it.
274	     * No such base means the target is not scouted now, as a player with an empty tank does not queue it.
275	     *
276	     * @param list<PlanetService> $origins
277	     */
278	    private function closestOrigin(PlayerService $player, array $origins, Planet $target, FleetMissionService $fleetMissions): PlanetService|null
279	    {
280	        $coordinate = new Coordinate((int) $target->galaxy, (int) $target->system, (int) $target->planet);
281	        $probe = ObjectService::getUnitObjectByMachineName(EspionageMission::getRequiredShipMachineNames()[0]);
282	        $best = null;
283	        $bestDistance = null;
284	
285	        foreach ($origins as $origin) {
286	            $units = new UnitCollection();
287	            $units->addUnit($probe, $this->probeCount($target));
288	            if (!app(FlightFuel::class)->affordable($player, $origin, $units, $coordinate, 10)) {
289	                continue;
290	            }
291	            $distance = $fleetMissions->calculateFleetMissionDistance($origin, $coordinate);
292	            if ($bestDistance === null || $distance < $bestDistance) {
293	                $best = $origin;
294	                $bestDistance = $distance;
295	            }
296	        }
297	
298	        return $best;
299	    }
