341	    /**
342	     * The last-known loot of each candidate, as metal-equivalent, from its most
343	     * recent report of any age. A never-probed planet scores zero here and is
344	     * ranked by closeness alone.
345	     *
346	     * Also says which of them the last report found defended (ships or defence standing), since the
347	     * scout that owns a war fleet reads the bodies that fight before the empty farms.
348	     *
349	     * @param iterable<int, Planet> $candidates
350	     * @return array{yield: array<string, float>, defended: array<string, true>}
351	     */
352	    private function knownIntelByCoordinate(iterable $candidates): array
353	    {
354	        $planets = is_array($candidates) ? $candidates : iterator_to_array($candidates);
355	        if ($planets === []) {
356	            return ['yield' => [], 'defended' => []];
357	        }
358	
359	        // One pass over the candidate coordinates instead of one report read per
360	        // candidate: the newest report per coordinate wins, so keep the first
361	        // (highest id) seen on the descending-id sweep.
362	        $reports = EspionageReport::query()
363	            ->where(function ($query) use ($planets): void {
364	                foreach ($planets as $planet) {
365	                    $query->orWhere(function ($coordinate) use ($planet): void {
366	                        $coordinate->where('planet_galaxy', $planet->galaxy)
367	                            ->where('planet_system', $planet->system)
368	                            ->where('planet_position', $planet->planet);
369	                    });
370	                }
371	            })
372	            ->orderByDesc('id')
373	            ->get(['id', 'planet_galaxy', 'planet_system', 'planet_position', 'resources', 'ships', 'defense']);
374	
375	        $yield = [];
376	        $defended = [];
377	        foreach ($reports as $report) {
378	            $key = "{$report->planet_galaxy}:{$report->planet_system}:{$report->planet_position}";
379	            if (isset($yield[$key])) {
380	                continue;
381	            }
382	
383	            $yield[$key] = $this->yieldFromResources($report->resources ?? []);
384	            if ($this->isDefended($report->ships, $report->defense)) {
385	                $defended[$key] = true;
386	            }
387	        }
388	
389	        return ['yield' => $yield, 'defended' => $defended];
390	    }
