392	    /**
393	     * Metal-equivalent of a report's visible resources, on the estimator's own weights.
394	     *
395	     * @param array<string, mixed> $resources
396	     */
397	    private function yieldFromResources(array $resources): float
398	    {
399	        return (float) ($resources['metal'] ?? 0)
400	            + 1.5 * (float) ($resources['crystal'] ?? 0)
401	            + 2.0 * (float) ($resources['deuterium'] ?? 0);
402	    }
