404	    /**
405	     * The coordinates the account already holds fresh intel on, keyed g:s:p.
406	     *
407	     * A report is reached through the account's own messages, the host's link
408	     * from a probe to the report it produced, and only reports inside the intel
409	     * window count. The window matches the observation service's TTL so scouting
410	     * and raiding agree on what "recently probed" means.
411	     *
412	     * @return array<string, true>
413	     */
414	    private function freshIntelCoordinates(int $playerId): array
415	    {
416	        $reportIds = Message::query()
417	            ->where('user_id', $playerId)
418	            ->whereNotNull('espionage_report_id')
419	            ->where('created_at', '>=', now()->subHours(self::INTEL_TTL_HOURS))
420	            ->pluck('espionage_report_id');
421	
422	        $coordinates = [];
423	        foreach (EspionageReport::query()->whereIn('id', $reportIds)->get(['planet_galaxy', 'planet_system', 'planet_position']) as $report) {
424	            $coordinates["{$report->planet_galaxy}:{$report->planet_system}:{$report->planet_position}"] = true;
425	        }
426	
427	        return $coordinates;
428	    }
429	
430	    /**
431	     * The coordinates this account already has an espionage probe travelling to,
432	     * keyed g:s:p. A probe that has not returned yet yields no report, so it has
433	     * to be skipped on its own signal rather than through fresh intel: firing a
434	     * second probe at the same planet before the first is back is the other half
435	     * of the re-probing loop the freshness guard alone cannot stop.
436	     *
437	     * @return array<string, true>
438	     */
439	    private function inFlightCoordinates(int $playerId): array
440	    {
441	        $coordinates = [];
442	        foreach (FleetMission::query()
443	            ->where('user_id', $playerId)
444	            ->where('mission_type', EspionageMission::getTypeId())
445	            ->where('processed', 0)
446	            ->where('canceled', 0)
447	            ->get(['galaxy_to', 'system_to', 'position_to']) as $mission) {
448	            $coordinates["{$mission->galaxy_to}:{$mission->system_to}:{$mission->position_to}"] = true;
449	        }
450	
451	        return $coordinates;
452	    }
453	
454	    /**
455	     * The coordinates this account has already decided to probe but not yet
456	     * dispatched, keyed g:s:p. A queued or retried intent sits between the
457	     * decision and the mission, and a report does not exist for it yet, so it
458	     * has to be skipped on its own signal: deciding to probe the same target
459	     * again every session while the earlier intent is still waiting is the
460	     * third leg of the re-probing loop, after fresh intel and the in-flight
461	     * mission.
462	     *
463	     * @return array<string, true>
464	     */
465	    private function openSpyIntentCoordinates(int $playerId): array
466	    {
467	        $coordinates = [];
468	        foreach (AiWorkItem::query()
469	            ->where('player_id', $playerId)
470	            ->where('kind', AiWorkKind::Spy)
471	            ->whereIn('state', [AiWorkState::Pending, AiWorkState::Leased, AiWorkState::Retry])
472	            ->get(['payload']) as $item) {
473	            $payload = $item->payload ?? [];
474	            if (isset($payload['target_galaxy'], $payload['target_system'], $payload['target_position'])) {
475	                $coordinates["{$payload['target_galaxy']}:{$payload['target_system']}:{$payload['target_position']}"] = true;
476	            }
477	        }
478	
479	        return $coordinates;
480	    }
481	}

