 15	/**
 16	 * Replays a saved scenario through the real decision engine without writing anything.
 17	 *
 18	 * A replay is how one decision is questioned without touching an account: the scenario names the
 19	 * persona, the legal observation and the frozen time, and the engine then has to produce the same
 20	 * answer on every run. That is the property worth having — a decision nobody can reproduce is a
 21	 * decision nobody can argue with.
 22	 *
 23	 * The persona is an unsaved profile, so replaying a scenario cannot create, change or enable an
 24	 * account, and every field is read through an explicit accessor: a malformed scenario reports
 25	 * which field is wrong instead of deciding from a half-read file.
 26	 */
 27	class ReplayAiScenarioAction
 28	{
 29	    /**
 30	     * A reserved id that no real account can hold, so the synthetic persona is never read from
 31	     * the profiles table even on a universe that has profiles.
 32	     */
 33	    private const SYNTHETIC_PLAYER_ID = 0;
 34	
 35	    private const SCENARIO_DIRECTORY = 'resources/scenarios';
 36	
 37	    /**
 38	     * The scenarios that ship with the module. The admin page can only replay one of these, so
 39	     * a page request cannot be turned into a read of an arbitrary file on the host.
 40	     *
 41	     * @return list<string>
 42	     */
 43	    public function names(): array
 44	    {
 45	        $names = [];
 46	
 47	        foreach (glob(module_path('AI', self::SCENARIO_DIRECTORY . '/*.json')) ?: [] as $path) {
 48	            $names[] = basename($path, '.json');
 49	        }
 50	
 51	        sort($names);
 52	
 53	        return $names;
 54	    }
 55	
 56	    public function pathFor(string $name): string
 57	    {
 58	        if (!in_array($name, $this->names(), true)) {
 59	            throw new RuntimeException('Unknown scenario: ' . $name . '. Known scenarios: ' . implode(', ', $this->names()) . '.');
 60	        }
 61	
 62	        return module_path('AI', self::SCENARIO_DIRECTORY . '/' . $name . '.json');
 63	    }
 64	
 65	    public function handle(string $path): AiScenarioReplay
 66	    {
 67	        $scenario = $this->load($path);
 68	        $perception = $this->perception($scenario);
 69	        $persona = $this->persona($scenario);
 70	        $decisionKey = (string) $this->scalar($scenario, 'decision_key');
 71	        $trace = app(DecisionEngine::class)->decide($persona, $perception, $decisionKey);
 72	        $selected = $trace->selected;
 73	        $replay = app()->makeWith(AiScenarioReplay::class, [
 74	            'name' => (string) $this->scalar($scenario, 'name'),
 75	            'persona' => $persona->archetype->name . '/' . $persona->skill_band->name . ' seed ' . $persona->random_seed,
 76	            'observedAt' => $perception->observedAt,
 77	            'decisionKey' => $decisionKey,
 78	            'selectedAction' => $selected->candidate->type->name,
 79	            'selectedReason' => $selected->candidate->reason,
 80	            'selectedScore' => $selected->score,
 81	            'components' => $selected->components,
 82	            'refusals' => $trace->rejections,
 83	            'alternatives' => $this->alternatives($trace->candidates),
 84	        ]);
 85	
 86	        $this->assertExpected($scenario, $replay);
 87	
 88	        return $replay;
 89	    }
 90	
 91	    /**
 92	     * Fail the replay when the engine did not do what the scenario says it must.
 93	     *
 94	     * Without `expect` a scenario only reports what happened. With it, the scenario becomes an
 95	     * acceptance check for one rule under the exact conditions it describes -- a player in this
 96	     * situation must take this action -- which is the difference between proving the rule works and
 97	     * proving a class exists.
 98	     *
 99	     * @param array<string, mixed> $scenario
100	     */
101	    private function assertExpected(array $scenario, AiScenarioReplay $replay): void
102	    {
103	        $expect = $scenario['expect'] ?? null;
104	        if (!is_array($expect)) {
105	            return;
106	        }
107	
108	        $action = $expect['action'] ?? null;
109	        if (is_string($action) && strcasecmp($action, $replay->selectedAction) !== 0) {
110	            throw new RuntimeException(sprintf(
111	                'Scenario expected action %s but the engine chose %s (%s). Alternatives: %s',
112	                $action,
113	                $replay->selectedAction,
114	                $replay->selectedReason,
115	                json_encode($replay->alternatives)
116	            ));
117	        }
118	
119	        $reason = $expect['reason_contains'] ?? null;
120	        if (is_string($reason) && !str_contains(strtolower($replay->selectedReason), strtolower($reason))) {
121	            throw new RuntimeException(sprintf(
122	                'Scenario expected the selected reason to contain "%s" but it was "%s".',
123	                $reason,
124	                $replay->selectedReason
125	            ));
126	        }
127	    }
128	
129	    /**
130	     * @return array<string, mixed>
131	     */
132	    private function load(string $path): array
133	    {
134	        if (!is_file($path)) {
135	            throw new RuntimeException('Scenario file not found: ' . $path);
136	        }
137	
138	        $decoded = json_decode((string) file_get_contents($path), true);
139	
140	        if (!is_array($decoded)) {
141	            throw new RuntimeException('Scenario is not valid JSON: ' . $path);
142	        }
143	
144	        // Presence is checked before anything is read, so a scenario that is missing a whole
145	        // section is reported as missing rather than as whatever field is read first.
146	        foreach (['name', 'persona', 'input', 'decision_key'] as $key) {
147	            if (!array_key_exists($key, $decoded)) {
148	                throw new RuntimeException('Scenario is missing "' . $key . '": ' . $path);
149	            }
150	        }
151	
152	        return $decoded;
153	    }
154	
155	    /**
156	     * @param array<string, mixed> $scenario
157	     */
158	    private function perception(array $scenario): PerceptionSnapshot
159	    {
160	        $input = $this->section($scenario, 'input');
161	
162	        return app()->makeWith(PerceptionSnapshot::class, [
163	            'playerId' => (int) $this->scalar($input, 'player_id'),
164	            'observedAt' => CarbonImmutable::parse((string) $this->scalar($input, 'observed_at')),
165	            'planets' => $this->planets($input),
166	            'targetReports' => $this->rows($input, 'target_reports'),
167	            'availableActions' => $this->flags($input, 'available_actions'),
168	            'fleetsaveEligible' => (bool) $this->scalar($input, 'fleetsave_eligible'),
169	            'recoveryFactor' => (float) $this->scalar($input, 'recovery_factor'),
170	            'sourceTimestamps' => $this->labels($input, 'source_timestamps'),
171	            'fleetSlotsFree' => (int) $this->scalar($input, 'fleet_slots_free'),
172	            'colonizeEligible' => (bool) $this->scalar($input, 'colonize_eligible'),
173	        ]);
174	    }
175	
176	    /**
177	     * The persona is named by case name rather than by stored value, because a scenario file is
178	     * written by a person and "Miner" says more than the number it happens to be stored as.
179	     *
180	     * @param array<string, mixed> $scenario
181	     */
182	    private function persona(array $scenario): AiProfile
183	    {
184	        $persona = $this->section($scenario, 'persona');
185	
186	        return AiProfile::query()->firstOrNew(['player_id' => self::SYNTHETIC_PLAYER_ID], [
187	            'archetype' => $this->archetype($persona),
188	            'skill_band' => $this->skillBand($persona),
189	            'random_seed' => (int) $this->scalar($persona, 'random_seed'),
190	            'enabled' => false,
191	        ]);
192	    }
193	
194	    /**
195	     * @param array<string, mixed> $persona
196	     */
197	    private function archetype(array $persona): AiArchetype
198	    {
199	        $name = (string) $this->scalar($persona, 'archetype');
200	
201	        foreach (AiArchetype::cases() as $case) {
202	            if (strcasecmp($case->name, $name) === 0) {
203	                return $case;
204	            }
205	        }
206	
207	        throw new RuntimeException('Scenario names an unknown archetype: ' . $name . '.');
208	    }
209	
210	    /**
211	     * @param array<string, mixed> $persona
212	     */
213	    private function skillBand(array $persona): AiSkillBand
214	    {
215	        $name = (string) $this->scalar($persona, 'skill_band');
216	
217	        foreach (AiSkillBand::cases() as $case) {
218	            if (strcasecmp($case->name, $name) === 0) {
219	                return $case;
220	            }
221	        }
222	
223	        throw new RuntimeException('Scenario names an unknown skill band: ' . $name . '.');
224	    }
225	
226	    /**
227	     * @param array<int, ScoredCandidate> $scored
228	     * @return array<int, array{action: string, score: float}>
229	     */
230	    private function alternatives(array $scored): array
231	    {
232	        return collect($scored)
233	            ->map(static fn ($candidate): array => [
234	                'action' => $candidate->candidate->type->name,
235	                'score' => $candidate->score,
236	            ])
237	            ->sortByDesc('score')
238	            ->values()
239	            ->all();
240	    }
241	
242	    /**
243	     * @param array<string, mixed> $source
244	     * @return array<int, array{id: int, resources: array<string, float|int>}>
245	     */
246	    private function planets(array $source): array
247	    {
248	        $planets = [];
249	
250	        foreach ($this->rows($source, 'planets') as $planet) {
251	            $resources = [];
252	
253	            foreach ($this->section($planet, 'resources') as $name => $amount) {
254	                if (!is_int($amount) && !is_float($amount)) {
255	                    throw new RuntimeException('Scenario planet resource "' . $name . '" must be a number.');
256	                }
257	
258	                $resources[(string) $name] = $amount;
259	            }
260	
261	            $planets[] = ['id' => (int) $this->scalar($planet, 'id'), 'resources' => $resources];
262	        }
263	
264	        return $planets;
265	    }
266	
267	    /**
268	     * @param array<string, mixed> $source
269	     * @return array<int, array<string, mixed>>
270	     */
271	    private function rows(array $source, string $key): array
272	    {
273	        $rows = [];
274	
275	        foreach ($this->section($source, $key) as $row) {
276	            if (!is_array($row)) {
277	                throw new RuntimeException('Scenario field "' . $key . '" must be a list of objects.');
278	            }
279	
280	            $rows[] = $row;
281	        }
282	
283	        return $rows;
284	    }
285	
286	    /**
287	     * @param array<string, mixed> $source
288	     * @return array<string, bool>
289	     */
290	    private function flags(array $source, string $key): array
291	    {
292	        $flags = [];
293	
294	        foreach ($this->section($source, $key) as $name => $value) {
295	            if (!is_bool($value)) {
296	                throw new RuntimeException('Scenario flag "' . $name . '" must be true or false.');
297	            }
298	
299	            $flags[(string) $name] = $value;
300	        }
301	
302	        return $flags;
303	    }
304	
305	    /**
306	     * @param array<string, mixed> $source
307	     * @return array<string, string>
308	     */
309	    private function labels(array $source, string $key): array
310	    {
311	        $labels = [];
312	
313	        foreach ($this->section($source, $key) as $name => $value) {
314	            if (!is_string($value)) {
315	                throw new RuntimeException('Scenario label "' . $name . '" must be a string.');
316	            }
317	
318	            $labels[(string) $name] = $value;
319	        }
320	
321	        return $labels;
322	    }
323	
324	    /**
325	     * @param array<string, mixed> $source
326	     * @return array<string, mixed>
327	     */
328	    private function section(array $source, string $key): array
329	    {
330	        $value = $source[$key] ?? null;
331	
332	        if (!is_array($value)) {
333	            throw new RuntimeException('Scenario field "' . $key . '" must be an object.');
334	        }
335	
336	        return $value;
337	    }
338	
339	    /**
340	     * @param array<string, mixed> $source
341	     */
342	    private function scalar(array $source, string $key): string|int|float|bool
343	    {
344	        $value = $source[$key] ?? null;
345	
346	        if (!is_scalar($value)) {
347	            throw new RuntimeException('Scenario field "' . $key . '" must be a scalar value.');
348	        }
349	
350	        return $value;
351	    }
352	}

