 22	/**
 23	 * Every authenticity signal the decision engine owns is pinned by one shipped scenario. The set
 24	 * is the replay evidence an operator or reviewer runs with `ai:replay-scenario <name>`; the
 25	 * assertions below are the properties the matrix promises, each under a frozen time and seed.
 26	 */
 27	const AUTHENTICITY_SCENARIOS = [
 28	    'miner-under-visible-raid',      // 1  reaction latency + save: the save fires under inbound
 29	    'late-notice-doomed-save',       // 1/6 a late notice is a doomed save, so a save can fail
 30	    'routine-21-days',               // 2  uptime shape: the dark period decides nothing
 31	    'economy-chain',                 // 3  growth curve: severe scarcity makes the mine the answer
 32	    'colonize-needs-development',    // 3  growth is gated: a colony is withheld until developable
 33	    'divergence-two-accounts',       // 4  self-similarity: two accounts answer differently
 34	    'spy-two-accounts',              // 11 aggregate stats: a free slot probes, score not pinned
 35	    'throttle-mine-when-short',      // 3  mining while short
 36	];
 37	
 38	/** Replays one shipped scenario through the real engine without writing anything. */
 39	function replayScenario(string $name): AiScenarioReplay
 40	{
 41	    return app(ReplayAiScenarioAction::class)->handle(app(ReplayAiScenarioAction::class)->pathFor($name));
 42	}
 43	
 44	/** @param array<string, mixed> $overrides */
 45	function replayScenarioWithOverrides(string $name, array $overrides): AiScenarioReplay
 46	{
 47	    $action = app(ReplayAiScenarioAction::class);
 48	    /** @var array<string, mixed> $scenario */
 49	    $scenario = json_decode((string) file_get_contents($action->pathFor($name)), true, 512, JSON_THROW_ON_ERROR);
 50	
 51	    foreach ($overrides as $field => $value) {
 52	        data_set($scenario, $field, $value);
 53	    }
 54	
 55	    $path = sys_get_temp_dir() . '/ai-scenario-' . uniqid('', true) . '.json';
 56	    file_put_contents($path, json_encode($scenario, JSON_THROW_ON_ERROR));
 57	
 58	    try {
 59	        return $action->handle($path);
 60	    } finally {
 61	        unlink($path);
 62	    }
 63	}
