456	
457	    /**
458	     * probe
459	     * The feature profile per action intent (specs/decision-doctrine.md D-table): resource_need is
460	     * economy pressure, safety is exposure removed, target_confidence intel quality, travel_cost
461	     * fuel, recovery the post-loss appetite. The host-derived values (confidence, travel_cost) arrive
462	     * per candidate; resource_need, safety and recovery are the floor a plan starts from, and the
463	     * errand's own plan replaces the floor when it can price it. Every capability a subject
464	     * account can queue is offered, so the choice among errands is the only question left.
465	     *
466	     * @return array{resource_need:float,safety:float,target_confidence:float,travel_cost:float,recovery:float}
467	     */
468	    private function features(AiCandidateActionType $type, float $resourceNeed, float $confidence, float $travelCost, float $recovery): array
469	    {
470	        [$need, $safety, $targetConfidence, $travel] = match ($type) {
471	            AiCandidateActionType::DoNothing => [0.0, 0.1, 0.0, 0.0],
472	            AiCandidateActionType::FleetSave => [0.0, 1.0, 0.0, 0.0],
473	            AiCandidateActionType::Recall => [0.0, 0.7, 0.0, 0.0],
474	            AiCandidateActionType::Expedition => [0.3, 0.6, 0.0, 0.0],
475	            // Only offered once the transfer planner found something worth moving, so it presses like a full
476	            // store; at 0.4 it never outranked an expedition and the cohort never moved a resource.
477	            AiCandidateActionType::Transfer => [0.9, 0.3, 0.0, 0.0],
478	            // The planner offers this only for a field above its own minimum mass with an own body
479	            // that carries the harvest hull or can build it, so the trip is already proved worth
480	            // taking: as pressing as a full store, the reading the raid row uses.
481	            AiCandidateActionType::Recycle => [1.0, 0.3, 0.0, 0.0],
482	            AiCandidateActionType::Phalanx => [0.5, 0.2, 0.3, 0.0],
483	            // An ally was just attacked and a co-member's combat hulls are idle at home: the help an
484	            // alliance exists for, as pressing as a full store so it is not outranked by a ferry.
485	            AiCandidateActionType::Defend => [0.9, 0.3, 0.0, 0.0],
486	            // Offered only when a store overflows beside a thin one and the account holds the dark matter.
487	            AiCandidateActionType::Trade => [0.8, 0.3, 0.0, 0.0],
488	            // A move the account can already pay for and that never stops improving the planet: a slow errand.
489	            AiCandidateActionType::Relocate => [0.6, 0.3, 0.0, 0.0],
490	            // A fleet standing at a threatened moon can leave at once: as pressing as a save.
491	            AiCandidateActionType::JumpGate => [1.0, 0.2, 0.0, 0.0],
492	            // The planner found a wall in range and missiles in the silo: as pressing as a raid it softens.
493	            AiCandidateActionType::Missile => [0.8, 0.2, 0.0, 0.0],
494	            // The planner has already proved this raid pays, so it is as pressing as a full store.
495	            AiCandidateActionType::Raid => [1.0, 0.1, $confidence, $travelCost],
496	            default => [$resourceNeed, 0.2, 0.0, 0.0],
497	        };
498	
499	        return [
500	            'resource_need' => $need,
501	            'safety' => $safety,
502	            'target_confidence' => $targetConfidence,
503	            'travel_cost' => $travel,
504	            'recovery' => $recovery,
505	        ];
506	    }
507	}

